#!/bin/zsh
# Aufruf: nohup paket.sh <issue> [konto] &   – alle Häppchen eines Pakets: Plan, Bau, CI, Urteil, Merge, nächstes Häppchen, ohne Höchstzahl (bis der Bau "Plan durch" meldet oder ein Halt kommt).
#   Sicherungen: höchstens 2 Rückläufe je PR, 120 min je Sitzung, Kettenplätze; sechster Start am selben Häppchen ohne Merge hält (starts.txt). Halte mit offener Frage beantwortet entscheiden() in einer Opus-Sitzung; Mensch nur bei Geld, Live, Zugangsdaten, Lockerung von Prüfungen, echter Produktabwägung.
#   konto: 1 = Standard-Login (ohne CLAUDE_CONFIG_DIR), 2 = ~/.claude-account2, 3 = ~/.claude-account3; ohne Angabe wie bisher (CLAUDE_CONFIG_DIR der Umgebung, sonst Konto 1).
# Verbrauch: paket.sh --verbrauch [stunden]   (/usage je Konto: Wochen-Prozent und Reset; dazu je Paket der letzten Stunden (Standard 24) Euro, davon Umfeld, Prozent Wochenlimit und Dauer Start bis letzter Merge, aus $KETTEN/paket-*/verbrauch.jsonl)
set -u
# EINE FASSUNG (24.11.2026): Diese Datei läuft unverändert auf dem Server und auf dem Mac. Bearbeitet wird sie nur auf dem Server;
# der Mac holt sie alle zwei Minuten (cloud/bau-vom-server-holen.sh). Unterschiede der Rechner stehen nur in den Zeilen mit MAC/LINUX.
MAC=; [[ $(uname) == Darwin ]] && MAC=1
[ -z "$MAC" ] && export PATH=$HOME/node22/bin:$PATH   # LINUX: Node 22 (Pflicht); Mac: Node 22 kommt aus homebrew node@22
sedi() { if [ -n "$MAC" ]; then sed -i '' "$@"; else sed -i "$@"; fi; }   # MAC/LINUX: BSD- und GNU-sed
sperre() { local d=$1; shift; if [ -n "$MAC" ]; then lockf -k -t 120 "$d" "$@"; else flock -w 120 "$d" "$@"; fi; }   # MAC/LINUX: lockf bzw. flock auf derselben Sperrdatei
MAX_KETTEN=14; [ -z "$MAC" ] && MAX_KETTEN=5   # MAC/LINUX: Höchstzahl gleichzeitiger Ketten je Rechner; Antonio legt die Werte fest (Mac 14; Server 5 seit 24.11., die Lastampel senkt sie, wenn er belegt ist, dann übernimmt der Mac)
# Zustand der Ketten (halt, wartet-auf, konto, verbrauch, Logs, Warteschlange): dauerhafter Ort, nicht /tmp (ein Rechnerneustart leerte /tmp, 13.11. 776 Paket-Minuten Halt "Ordner fehlt"). Einzige Stelle; die Leser (verteiler.json ketten.tmp, bauweg.py, aufraeumen.py, stillstand.py) lesen denselben Pfad.
KETTEN=${KETTEN:-/Users/antonio/Bereiche/sundartha/engineering/ketten}; export KETTEN; mkdir -p $KETTEN
ALT_TMP=${ALT_TMP:-/tmp}   # Altbestand vor dem Umzug (14.11.): wird je Nummer und für die Warteschlange hierher übernommen, bis /tmp leer ist
alt_schlange() { [ -f $ALT_TMP/paket-warteschlange.txt ] || return 0; touch $KETTEN/paket-warteschlange.txt; while read -r z; do [ -n "$z" ] && { grep -qs "^${z%% *} " $KETTEN/paket-warteschlange.txt || echo "$z" >> $KETTEN/paket-warteschlange.txt; }; done < $ALT_TMP/paket-warteschlange.txt; /bin/rm -f $ALT_TMP/paket-warteschlange.txt; }

if [ "$1" = "--verbrauch" ]; then
  for K in 1 2 3; do   # genauer Stand je Konto bis zum Reset (lokaler Befehl, kein Modellaufruf)
    D=$(case $K in 1) ;; 2) echo /Users/antonio/.claude-account2 ;; 3) echo /Users/antonio/.claude-account3 ;; esac)
    echo "Konto $K: $( (cd /tmp; if [ -n "$D" ]; then KONTO_FEST=1 CLAUDE_KONTO=$K env -u CLAUDE_CODE_OAUTH_TOKEN CLAUDE_CONFIG_DIR=$D /Users/antonio/.local/bin/claude -p /usage; else KONTO_FEST=1 CLAUDE_KONTO=$K env -u CLAUDE_CODE_OAUTH_TOKEN -u CLAUDE_CONFIG_DIR /Users/antonio/.local/bin/claude -p /usage; fi) 2>&1 | grep -E '^Current (session|week .all models)' | tr '\n' ' ')"
  done
  EUR=0.896; EICH=17; UMF='{"1":1.7,"2":0.5}'   # EZB-Referenzkurs 06.11.2026: 1 EUR = 1,1165 USD. EICH = Dollar je 1 % Wochenlimit eines Kontos (08.11.: Summe aller Sitzungen des Kontos seit Reset / Wochen-%: Konto 1 18,6; Konto 2 14,2; Konto 3 17,8)
  # UMF = Umfeld-Aufschlag je Konto: Dollar der Sitzungen des Kontos, die nicht aus paket.sh stammen (Wache, Leiter, Engineering-Chats), je Paket-Dollar, gemessen 08.11. 14:03-20:30 (Konto 1: 102 $ zu 59 $; Konto 2: 31 $ zu 63 $); fremde Themen (Telcoradar, Produkt, PowerBI) nicht gerechnet. Grob (±50 %), bei Bedarf neu messen.
  SEIT=$(( $(date +%s) - ${2:-24} * 3600 )); echo "Pakete der letzten ${2:-24} h (1 % Woche = $EICH \$, 1 \$ = $EUR €; Euro = Paket samt Unteragenten plus Umfeld):"
  for D in $KETTEN/paket-[0-9]*(/); do
    jq -s -r --arg i ${D:t:s/paket-//} --argjson s $SEIT --argjson e $EUR --argjson c $EICH --argjson f $UMF --arg a "$(cat $D/start.txt 2>/dev/null)" --arg m "$(tail -1 $D/gemergt.txt 2>/dev/null | cut -d' ' -f2)" '
      select((map(.ende // 0) | max) >= $s) | (map(.kosten_usd // 0) | add) as $d | (map((.kosten_usd // 0) * ($f[.konto // "0"] // 0)) | add) as $o | ($d + $o) as $u | now as $j |
      ((if $m == "" then $j else ($m | fromdateiso8601) end) - ($a | if . == "" then $j else fromdateiso8601 end) | ./60 | floor) as $min |
      "#\($i)\t\(map(.konto // empty) | unique | join("+"))\t\($u * $e * 10 | round / 10) €\t\($o * $e * 10 | round / 10) €\t\($u / $c * 10 | round / 10) %\t\($min / 60 | floor) h \($min % 60) min\(if $m == "" then " (läuft)" else "" end)"' $D/verbrauch.jsonl 2>/dev/null
  done | sort -t$'\t' -k3 -rn | { printf 'Paket\tKonto\tEuro\tdavon Umfeld\t%% Woche\tDauer\n'; cat; } | column -t -s$'\t'
  exit 0
fi
ISSUE=$1
[ -z "${PAKET_SCOPE:-}" ] && command -v systemd-run >/dev/null && systemd-run --user --scope -q true 2>/dev/null && PAKET_SCOPE=1 exec systemd-run --user --scope --collect -q --unit=paket-$ISSUE-$(date +%s) -- setsid -f "${0:A}" "$@"   # 20.11. Claude: setsid -f = eigene Prozessgruppe; um 11:45 starben drei Ketten mit dem Ende des Engineering-Weckerlaufs (Rücknahme: cp -p paket.sh.vor-setsid-1120 paket.sh). Antonio 18.11.: Ketten außerhalb des Gateway-Cgroups (ein Gateway-Neustart tötete 22:44 alle Ketten)
case "${2:-}" in
  1) unset CLAUDE_CONFIG_DIR ;;   # Konto 1 = Standard; CLAUDE_CONFIG_DIR=~/.claude ist NICHT dasselbe (kein Abo-Login)
  2) export CLAUDE_CONFIG_DIR=/Users/antonio/.claude-account2 ;;
  3) export CLAUDE_CONFIG_DIR=/Users/antonio/.claude-account3 ;;
  "") ;;
  *) echo "Konto muss 1, 2 oder 3 sein" >&2; exit 2 ;;
esac
# KONTO-AUTO-1120 (Antonio 19.11.: „das System soll automatisch auswählen, über welches Konto die Sitzung läuft“): ein angegebenes Konto gilt,
# solange es nicht voll ist, sonst das beste freie laut Abo-Router (~/.local/bin/konto-wahl, Datei vom Server). Ersetzt die feste Konto-1-Umleitung. Rücknahme: cp -p paket.sh.vor-konto-auto-1120 paket.sh
_kw=${2:-}; [ -z "$_kw" ] && case "${CLAUDE_CONFIG_DIR:-}" in *account2) _kw=2 ;; *account3) _kw=3 ;; esac; _kn=$(/Users/antonio/.local/bin/konto-wahl $_kw 2>/dev/null); case "$_kn" in 1) unset CLAUDE_CONFIG_DIR ;; 2) export CLAUDE_CONFIG_DIR=/Users/antonio/.claude-account2 ;; 3) export CLAUDE_CONFIG_DIR=/Users/antonio/.claude-account3 ;; esac; if [ -n "$_kw" ] && [ -n "$_kn" ] && [ "$_kn" != "$_kw" ]; then echo "Konto $_kw ist voll, die Kette läuft über Konto $_kn" >&2; fi
_kn=1; case "${CLAUDE_CONFIG_DIR:-}" in *account2) _kn=2 ;; *account3) _kn=3 ;; esac; [[ -f $HOME/.config/openclaw-konten/konto$_kn.env ]] && export $(grep -h ^CLAUDE_CODE_OAUTH_TOKEN= $HOME/.config/openclaw-konten/konto$_kn.env)   # Server: Abo-Schluessel je Konto
KONTO=$(case "${CLAUDE_CONFIG_DIR:-}" in *account2) echo 2 ;; *account3) echo 3 ;; *) echo 1 ;; esac)
REPO="/Users/antonio/Mein Unternehmen/MCP/wt-steuerung"
gitr() { local _i _r; for _i in 1 2 3 4 5 6; do if [[ $(uname) == Darwin ]]; then lockf -k -t 120 "$KETTEN/wt-steuerung.lock" git -C "$REPO" "$@"; else flock -w 120 "$KETTEN/wt-steuerung.lock" git -C "$REPO" "$@"; fi; _r=$?; [ $_r -ne 0 ] && [ -f "$REPO/.git/index.lock" ] && { sleep $((RANDOM % 5 + 2)); continue; }; return $_r; done; return $_r; }   # 21.11.: alle Git-Aufrufe im gemeinsamen Ordner wt-steuerung laufen unter einer Sperre (lockf, wie die Warteschlange); ein index.lock-Zusammenstoß wird wiederholt und zählt nicht gegen die Startgrenze (Issue 5760)
LOG=$KETTEN/paket-$ISSUE; CLAUDE=/Users/antonio/.local/bin/claude
KEINPLAN="Haltmeldungen der Kette sind kein Plan und kein Grund, nichts zu starten: Issue-Kommentare, deren erste Zeile mit „Kette #“, „Paket hält“ oder „PR https://“ beginnt, überspringst du beim Lesen des Plans; der Plan im Issue und alle Plan-Nachträge (erste Zeile „Plan-Nachtrag“) gelten wie bisher."   # Haltmeldungen stehen als Kommentar im Issue; der Bau las sie als Plan-Nachtrag und startete nichts (#4397, 14.11.); Kopf-Liste = erste Zeilen der melden()-/Halt-Kommentare Z.71/171/175/189
[ -d $ALT_TMP/paket-$ISSUE ] && [ ! -L $ALT_TMP/paket-$ISSUE ] && [ ! -e $LOG ] && mv $ALT_TMP/paket-$ISSUE $LOG && ln -s $LOG $ALT_TMP/paket-$ISSUE   # Altbestand aus /tmp übernehmen (laufende Sitzungen mit dem alten Pfad finden ihn über den Verweis)
alt_schlange
APPU="/Users/antonio/Claude/Projects/Agentic Calling MCP/pakete-prompts/app-umgebung.sh"
gh() { GH_TOKEN="$("${APPU:h}/app-token.sh")" /opt/homebrew/bin/gh "$@"; }   # Lesen und Kommentieren über die App (15.000 core / 10.000 GraphQL je Stunde, Token 45 Min. zwischengespeichert): das Nutzerkonto hat nur 5.000 je Stunde und war mit 19 Ketten und der Wache erschöpft (17.11.); Antonios Rechte (Approve, Einreihen) laufen weiter über antonio()
mkdir -p $LOG/bin && ln -sf "${APPU:h}/.bin/paket-push" "${APPU:h}/.bin/paket-pr" "${APPU:h}/.bin/paket-kommentar" $LOG/bin/   # der einzige Push-, PR- und Issue-Kommentar-Weg der Sitzungen, ohne die übrigen Hüllen aus .bin (semgrep, claude) in den PATH zu holen
pcmd() { [ -n "${1:-}" ] || return 0; ps -o command= -p $1 2>/dev/null | tr '\n' ' ' | cut -c1-300; }   # Befehlszeile eines Prozesses, einzeilig; fehlende PID (Elternprozess schon weg) ergibt leer statt Abbruch unter set -u (#5473)
phase() { local T=$LOG/.phase-$$-$RANDOM F=null A; A=$(print -r -- "${2:-}" | tr -d '"\\\000-\037' | cut -c1-200 | iconv -c -f UTF-8 -t UTF-8 2>/dev/null); [ "${3:-0}" -gt 0 ] 2>/dev/null && F=$(( $(date +%s) + $3 )); { print -r -- "{\"phase\":\"$1\",\"seit\":$(date +%s),\"wartet_auf\":\"$A\",\"frist\":$F,\"pid\":${4:-$$}}" > $T && mv -f $T $LOG/phase; } 2>/dev/null || rm -f $T 2>/dev/null; return 0; }   # LAGE-1115: phase <name> <wartet_auf> <frist_s|0> [pid] schreibt $LOG/phase (eine Zeile JSON, erst temporär, dann mv); Fehler brechen die Kette nie ab
start_log() { echo "$(date -u +%FT%TZ) $ISSUE $KONTO $1 | PPID $PPID: $(pcmd $PPID) | Groß: $(pcmd $(ps -o ppid= -p $PPID)) | CLAUDE_CONFIG_DIR=${CLAUDE_CONFIG_DIR:-} | $(env | grep -E '^[^=]*(SESSION|AGENT)[^=]*=' | grep -viE '^[^=]*(KEY|TOKEN|SECRET)' | cut -c1-200 | tr '\n' ' ')| pwd=$PWD" >> $KETTEN/paket-starts.log; }
[ -f $LOG/halt-bis.txt ] && { start_log gesperrt; echo "$ISSUE gesperrt: $(cat $LOG/halt-bis.txt)" | tee -a $LOG/halt.txt >&2; exit 5; }   # Sperre bis zu einer Entscheidung: kein Start, kein Neustart; Rücknahme: Datei löschen
if ! mkdir $LOG/.lauf 2>/dev/null; then   # Sperre je Nummer: läuft die Kette dieser Nummer schon, abweisen; ist ihre PID tot, übernehmen
  P=$(cat $LOG/.lauf/pid 2>/dev/null); [ -n "$P" ] && kill -0 $P 2>/dev/null && { start_log doppelt; echo "$ISSUE läuft schon (PID $P)" >&2; exit 4; }
fi
# Kein Start ohne Karte (13.11.2026): Die Kette steht als Karte des Workboards (Agent, der sie gestartet hat; Auftragskarte, wenn es eine gibt), bevor der erste Schritt läuft.
if [ "${PAKET_OHNE_KARTE:-}" != 1 ]; then
  beginn_karte=$(date -u +%FT%TZ)
  KARTE_OK=0; for V in $(seq 1 20); do /opt/homebrew/bin/python3 -W ignore /Users/antonio/Bereiche/openclaw/karten/kette_start.py $ISSUE $KONTO >> $LOG/karte.log 2>&1 && { KARTE_OK=1; break; }; sleep 30; done   # 16.11.: Board-Sperre dauerte Minuten; 20 Versuche à 30 s statt 3 à 5 s
  if [ "$KARTE_OK" != 1 ]; then
    # start.txt erfasst den ersten Startversuch. Erst .start bestätigt den Arbeitsbeginn.
    if (setopt noclobber; print -r -- "$beginn_karte" > "$LOG/start.txt") 2>/dev/null; then
      touch -r "$LOG/.lauf" "$LOG/start.txt"
    fi
    grund_start="paket.sh: Aufgabenkarte nicht bestätigt. Arbeit nicht begonnen. Einzelheiten in karte.log."
    print -r -- "$grund_start" >> "$LOG/halt.txt"
    phase halt "$grund_start" 0
    start_log karte-fehlt
    rmdir "$LOG/.lauf" 2>/dev/null
    print -u2 -- "$ISSUE: $grund_start"
    exit 6
  fi
fi
echo $$ > $LOG/.lauf/pid; trap 'ende $?' EXIT
PRS="Prüfregel-Dateien (eslint.config.js, tools/eslint-rules, tools/bausteine.json, .dependency-cruiser.cjs u. ä.) ändert der Bau normal auf paket/* und pusht sie, wenn der Plan es verlangt; die rote Freigabe-Prüfung deswegen ist erwartet, nach PASS zieht die Kette den PR selbst auf system/* um (umzug). Lockerungen von Prüfungen bleiben verboten."   # Bau-, Rücklauf- und Entscheider-Brief (#3778 hielt, weil der Bau die Sperre für unüberwindbar hielt, 10.11.)
naechster() { case "$1" in   # nächster Schritt je Halt (Befund 7, 09.11.)
  "Bau ohne PR-Nummer"*) echo "bau-Log in $KETTEN/paket-$ISSUE lesen (der Grund steht im Halt). Plan prüfen, dann Kette neu starten." ;; *Migration*) echo "Antonio prüft und mergt den PR. Danach Kette neu starten." ;; *"falschem Konto"*) echo "PR schließen und unter der App neu eröffnen, dann Kette neu starten." ;; *FREIGABE*|*"wartet auf Freigabe"*) echo "Antonio oder Jonas entscheidet die genannte Freigabe. Danach Kette neu starten." ;; *URSACHE:*) echo "Die genannte Ursache beheben (Plan, Werkzeug, Test oder Umgebung). Danach Kette neu starten; zwei Rückläufe zählen ab einem neuen Schnitt." ;;
  *) case "$(grund "$1")" in mensch) echo "Halt-Grund und Logs in $KETTEN/paket-$ISSUE lesen, Ursache beheben, dann Kette neu starten." ;; *) echo "Kein Mensch nötig: Die Kette hat sich dreimal selbst neu gestartet (Kennwort $(cat $LOG/halt-grund.txt), Zähler in $LOG/halt-neustarts.txt), der Grund bleibt. Log der letzten Sitzung in $KETTEN/paket-$ISSUE ansehen, Ursache beheben, Kette neu starten." ;; esac ;; esac; }
entscheiden() {   # Halt mit offener Frage: eine Opus-Sitzung entscheidet an Stelle der Engineering-Leitung und schreibt einen Plan-Nachtrag, dann startet die Kette neu; Mensch nur bei Geld, Live, Zugangsdaten, Freigaben, Lockerung (Antonio 10.11.: Warten auf Entscheidungen auf null; Halte = 35 % der Paketzeit, nachts Stunden). Höchstens 2 je Häppchen.
  case "$1" in "Bau ohne PR-Nummer"*|URSACHE:*|*"Bewertung nach zwei Rückläufen ohne Ergebnis"*|*"ENTSCHEIDUNG NÖTIG"*|*"Frage an"*|*"offene Frage"*|*"Entscheidung fehlt"*|*"wartet auf Freigabe"*) ;; *) return 1 ;; esac   # jeder Halt, der eine offene Frage oder Entscheidung meldet, auch aus der Planung (Antonio 10.11.: Fragen beantwortet eine Sitzung im System, nicht Engineering und nicht Antonio)
  local H=$(( $(cat $LOG/gemergt.txt 2>/dev/null | wc -l) + 1 )); [ "$(grep -cx "$H" $LOG/entschieden.txt 2>/dev/null || true)" -ge 2 ] && return 1
  echo $H >> $LOG/entschieden.txt; local E=entscheiden-$H-$(grep -cx "$H" $LOG/entschieden.txt)
  sitzung $E "$KEINPLAN Die Kette für Issue #$ISSUE (sundartha/hermes) hält: „$1“. Du entscheidest an Stelle der Engineering-Leitung, damit die Kette nicht auf einen Menschen wartet. Lies das Issue samt Plan und allen Plan-Nachträgen, das neueste bau-*.log in $LOG und, falls es einen offenen PR zum Issue gibt (Kopf paket/$ISSUE-* oder system/$ISSUE-*, oder im Text 'Refs #$ISSUE', 'Closes #$ISSUE' oder 'Teil von #$ISSUE'), dessen letzten Urteilskommentar und die roten Läufe auf seinem aktuellen Kopf (gh run view --log-failed). Entscheide die offene Frage nach der Absicht des Issues und CLAUDE.md: der einfachste Weg, der die Abnahmekriterien hält. Prüfungen werden nicht gelockert; Erwartungen bestehender Tests ändern sich nur, wenn es aus dem Issue folgt. $PRS Du änderst keinen Code, schreibst nichts auf GitHub und startest keine Tests. Kannst du entscheiden: schreib die Anweisung für den Bau zwischen eine Zeile NACHTRAG-ANFANG und eine Zeile NACHTRAG-ENDE (Entscheidung, Begründung in einem Satz, konkrete Schritte mit Dateien), letzte Zeile genau ENTSCHIEDEN. Fragen aus der Planung (z. B. F2, F3, F5, Testattrappen, Zuschnitt, Wege A/B/C) beantwortest du alle selbst, jede einzeln im Nachtrag. NUR wenn eine Frage zu einer dieser fünf Klassen gehört, ist die letzte Zeile MENSCH: <die Frage in einem Satz>: (1) Geld, (2) ein Schritt auf Live, (3) Zugangsdaten oder Geheimnisse, (4) Daten löschen, Dritte oder nach außen, eine Sicherheitsgrenze oder eine Datenbank-Migration mergen, (5) die Charta oder der Ergebnisvertrag (Antonios Liste vom 06.11.). Lockerungen von Prüfungen und Produktabwägungen entscheidest du selbst: Prüfungen werden nicht gelockert, und eine Lockerung wäre eine Frage an Engineering, nie an Antonio. Alles andere entscheidest du selbst. Sind mehrere Fragen offen und nur einige menschlich: entscheide die übrigen im Nachtrag und antworte MENSCH: nur zur menschlichen."
  tail -1 $LOG/$E.log | grep -q '^MENSCH:' && { tail -1 $LOG/$E.log >> $LOG/halt.txt; return 1; }
  tail -1 $LOG/$E.log | grep -qx ENTSCHIEDEN || return 1
  ( source "$APPU" > /dev/null && gh issue comment $ISSUE -R sundartha/hermes --body "Plan-Nachtrag (Entscheidung der Kette zum Halt: ${1:0:200})
$(sed -n '/^NACHTRAG-ANFANG$/,/^NACHTRAG-ENDE$/p' $LOG/$E.log | sed '1d;$d')" > /dev/null 2>&1 ) || return 1
  echo "$(date -u +%FT%TZ) $E $1" >> $LOG/entscheidungen.txt; mv $LOG/halt.txt $LOG/halt-entschieden-$(date +%s).txt
  ( sleep 10; cd $SKRIPT; nohup ./paket.sh $ISSUE $KONTO >> $LOG/kette.out 2>&1 & ) & }
grund() { case "$1" in *Umgebung*) echo umgebung ;; *"PASS, aber"*) echo pass-checks-rot ;; *"ohne Ergebnis"*) echo bewertung-ohne-ergebnis ;; *"aus der Queue"*) echo queue-abwurf ;; *"sechster Start"*) echo startgrenze ;; "wartet auf PR"*) echo wartet-pr ;; MENSCH:*|*FREIGABE*|*"wartet auf Freigabe"*|*"Migration –"*|*Zugangsdaten*|*Sicherheitsgrenze*) echo mensch ;; *) echo sonst ;; esac; }   # festes Kennwort je Halt (halt-grund.txt); mensch NUR für Antonios Liste (MENSCH:, Freigabe, Migration mergen, Zugangsdaten, Sicherheitsgrenze); alles andere = sonst (Entscheider, Selbstneustart, Wache); 16.11. 22:50 erneut gesetzt, nicht zurücknehmen (Beleg: halt-frage-vorher-nachher-20261116.md)
melden() { gh issue comment $ISSUE -R sundartha/hermes --body "Kette #$ISSUE hält: $1"$'\n'"Nächster Schritt: $2" > /dev/null 2>&1; /usr/bin/python3 ~/Documents/OpenClaw-Plugins/verteiler/verteiler.py ereignis sundartha-produkt "halt:$ISSUE" "Kette #$ISSUE hält: $1 – Nächster Schritt: $2" > /dev/null 2>&1 || { [ -n "$STARTER" ] && openclaw system event --session-key "agent:$STARTER:main" --mode now --text "paket.sh $ISSUE hält: $1 – Nächster Schritt: $2" > /dev/null 2>&1; }; }   # 12.11.: Halt geht als Ereignis an die Auftragskarte von Hermes-Produkt (ein Weg, ein Kopf); nur ohne Auftragskarte wie früher an die Hauptsitzung des Starters
selbstneustart() {   # Halt ohne Mensch (13.11., Schritt 1): nach PAKET_WARTE s (15 min) startet die Kette sich selbst neu, höchstens dreimal je Grund und Häppchen; startgrenze bleibt stehen. Warten endet früher, sobald die Ursache weg ist (PR gemergt oder keine roten Prüfungen mehr; Abfrage alle PAKET_POLL s = 60; Halt ohne PR-Nummer: Neustart schon nach PAKET_WARTE_OHNE_PR (2) Abfragen statt 15 min, 17.11. Leerlauf-Hebel: 14 Lücken von 15–18 min in 12 Paketen); wartet-pr: ohne Modell jede Minute prüfen, ob der PR gemergt ist (höchstens 24 h) wartet-auf.txt weg = ein anderes Ende hat die Kette schon nachgezogen
  case $1 in mensch|startgrenze) return 1 ;; esac; local W=${PAKET_WARTE:-900} H=$(( $(cat $LOG/gemergt.txt 2>/dev/null | wc -l) + 1 )); if [ $1 = wartet-pr ]; then [ -f $LOG/wartet-auf.txt ] || return 1; else [ "$(grep -cx "$1 $H" $LOG/halt-neustarts.txt 2>/dev/null)" -ge 3 ] && return 1; fi; if ! mkdir $LOG/.wartet 2>/dev/null; then local WL=$(cat $LOG/.wartet/pid 2>/dev/null); if [ -n "$WL" ] && [ "$WL" != "$$" ] && kill -0 $WL 2>/dev/null && [[ "$(pcmd $WL)" == *"paket.sh $ISSUE "* ]]; then pkill -P $WL 2>/dev/null; kill $WL 2>/dev/null; fi; fi; echo "$1 $H" >> $LOG/halt-neustarts.txt; ( trap 'rm -rf $LOG/.wartet' EXIT; local n=0 S=closed P=${PAKET_POLL:-60}; if [ $1 = wartet-pr ]; then while [ -f $LOG/wartet-auf.txt ] && [ $((n+=1)) -le $((96 * W / P)) ]; do sleep $P; S=$(gh api repos/sundartha/hermes/issues/$(cat $LOG/wartet-auf.txt 2>/dev/null) --jq .state 2>/dev/null); [ "$S" = closed ] && break; done; [ -f $LOG/wartet-auf.txt ] || exit 0; else local R=$(grep -oE 'PR [0-9]+' $LOG/halt.txt 2>/dev/null | tail -1 | cut -d' ' -f2) Q; while [ $((n+=1)) -le $((W / P)) ]; do sleep $P; [ -n "$R" ] || { [ $n -ge ${PAKET_WARTE_OHNE_PR:-2} ] && break; continue; }; Q=$(gh pr view $R -R sundartha/hermes --json state,statusCheckRollup --jq '[.state, ([.statusCheckRollup[] | select((.conclusion // "") | IN("FAILURE","TIMED_OUT","CANCELLED","ACTION_REQUIRED","STARTUP_FAILURE"))] | length)] | join(" ")' 2>/dev/null); case "${Q% *}" in MERGED|CLOSED) break ;; esac; [ "$Q" = "OPEN 0" ] && break; done; fi; [ "$S" = closed ] || { melden "wartet auf PR $(cat $LOG/wartet-auf.txt 2>/dev/null): nach $n Prüfungen nicht gemergt (Stand $S)" "PR ansehen, dann Kette neu starten."; exit 0; }; trap - EXIT; rm -rf $LOG/.wartet; cd $SKRIPT; PAKET_STARTGRUND=$1 nohup ${PAKET_NEUSTART:-./paket.sh} $ISSUE $KONTO >> $LOG/kette.out 2>&1 ) > /dev/null 2>&1 & local WP=$!; echo $WP > $LOG/.wartet/pid 2>/dev/null; if [ $1 = wartet-pr ]; then phase wartet-pr "PR $(cat $LOG/wartet-auf.txt 2>/dev/null)" 0 $WP; else phase halt "Selbstneustart nach $((W / 60)) min ($1)" 0 $WP; fi; return 0; }   # wartet-auf.txt weg = ein anderes Ende hat die Kette schon nachgezogen   # LAGE-1115: höchstens ein Wartender je Nummer (Sperre $LOG/.wartet/pid; lebt dort schon einer, wird er beendet und der neueste Halt übernimmt; tote Sperre wird übernommen; vor dem Neustart frei)
halt_behandeln() { local H=$(tail -1 $LOG/halt.txt); entscheiden "$H" && return; H=$(tail -1 $LOG/halt.txt); local G=$(grund "$H"); echo $G > $LOG/halt-grund.txt; selbstneustart $G && return; local S=$(naechster "$H"); echo "Nächster Schritt: $S" >> $LOG/halt.txt; phase halt "$H" 0; melden "$H" "$S"; }   # erst die Entscheider-Sitzung (Fragen), dann Selbst-Neustart, erst danach melden
park_vorbei() {   # A-55NDA7: 0 = Parkzeit (halt-bis.txt, erste Zeile "JJJJ-MM-TT Grund") ist abgelaufen UND die Kette gehört diesem Rechner (kein auf-mac.txt) UND kein Mensch ist gefragt UND die Startbremse (fünf Starts am selben Häppchen, starts.txt) ist nicht erreicht
  local D=$1 T; T=$(head -1 $D/halt-bis.txt 2>/dev/null); [[ $T =~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([[:space:]]|$)' ]] || return 1
  [[ ${T[1,10]} > $(TZ=Europe/Berlin date +%F) ]] && return 1
  grep -qiE 'antonio|jonas|freigabe|mensch' $D/halt-bis.txt && return 1
  [ -e $D/auf-mac.txt ] && return 1
  case "$(cat $D/halt-grund.txt 2>/dev/null)" in mensch|startgrenze) return 1 ;; esac
  [ "$(sort $D/starts.txt 2>/dev/null | uniq -c | sort -rn | awk 'NR==1{print $1+0}')" -ge 5 ] && return 1
  return 0
}
einreihen_freigegebene() {   # A-55NDA7: offene PR der Ketten (paket/*, system/*, nicht Entwurf) mit Approve von Antonio20045/jonas986 auf dem Kopf (approve) UND mergeStateStatus CLEAN (alle Pflicht-Checks grün) UND nicht in der Queue (eingereiht): einmal je Kopf einreihen (einreihen.txt). Keine Prüfung wird gelockert: ohne Approve oder mit rotem Pflicht-Check bleibt GitHub bei BLOCKED und nichts passiert.
  local n k s
  gh pr list -R sundartha/hermes --state open --limit 100 --json number,headRefName,headRefOid,isDraft,mergeStateStatus --jq '.[] | select((.isDraft | not) and (.mergeStateStatus == "CLEAN") and (.headRefName | test("^(paket|system)/"))) | "\(.number) \(.headRefOid)"' 2>/dev/null | while read -r n k; do
    [ -n "$k" ] && ! grep -qsx "$n $k" $KETTEN/einreihen.txt && approve $n $k && ! eingereiht $n || continue
    echo "$n $k" >> $KETTEN/einreihen.txt; antonio pr merge $n -R sundartha/hermes --rebase --auto > /dev/null 2>&1 && echo "PR $n: von paket.sh eingereiht (freigegeben, grün)" >> $KETTEN/nachgetragen.txt
  done
  gh pr list -R sundartha/hermes --state open --limit 100 --json number,headRefName,headRefOid,isDraft,mergeStateStatus --jq '.[] | select((.isDraft | not) and (.mergeStateStatus == "BLOCKED") and (.headRefName | test("^(paket|system)/"))) | "\(.number) \(.headRefOid)"' 2>/dev/null | while read -r n k; do   # A-TJATPQ: freigegeben (Approve auf dem Kopf), aber BLOCKED durch einen alten roten Lauf: einmal je Kopf neu starten (rerun.txt)
    [ -n "$k" ] && ! grep -qsx "$n $k" $KETTEN/rerun.txt && approve $n $k && gh pr checks $n -R sundartha/hermes 2>/dev/null | awk -F'\t' '$2 == "fail" {f = 1} END {exit !f}' || continue
    echo "$n $k" >> $KETTEN/rerun.txt; rote_neu $n; echo "PR $n: alte rote Läufe von paket.sh neu gestartet (freigegeben, BLOCKED)" >> $KETTEN/nachgetragen.txt
  done
}
ende() { rm -rf $LOG/.lauf; [ -n "${LAEUFT:-}" ] && [ -z "${PAKET_PROBE:-}" ] || return   # Halt sofort melden ohne Modelllauf (Befund 1) und Warteschlange nachrücken (Befund 7)
  if [ "$1" != 0 ] && [ $LOG/halt.txt -nt $LOG/.start ]; then phase halt "$(tail -1 $LOG/halt.txt)" 0; halt_behandeln; fi; [ "$1" = 0 ] && [ $LOG/fertig.txt -nt $LOG/.start ] && phase fertig "" 0   # LAGE-1115: Phase halt bzw. fertig
  alt_schlange
  for F in $KETTEN/paket-[0-9]*/wartet-auf.txt(N); do local I=${${F:h:t}#paket-}; [ "$(gh api repos/sundartha/hermes/issues/$(cat $F) --jq .state 2>/dev/null)" = closed ] || continue   # Abhängigkeit gemergt: Paket rückt von selbst nach (10.11.: ~20 h Kettenleerlauf durch Warten auf PRs)
    rm -f $F; grep -qs "^$I " $KETTEN/paket-warteschlange.txt || echo "$I $(tail -1 ${F:h}/konto.txt 2>/dev/null | cut -d' ' -f1 | grep -E '^[123]$' || echo 1) $(date -u +%FT%TZ) abhaengigkeit" >> $KETTEN/paket-warteschlange.txt; done
  for F in $KETTEN/paket-[0-9]*/halt-bis.txt(N); do local I=${${F:h:t}#paket-}; [ "$I" = "$ISSUE" ] && continue; park_vorbei ${F:h} || continue   # A-55NDA7: Parkzeit abgelaufen: die Sperre wird umbenannt (nicht gelöscht; sie ist zugleich der Marker gegen Dauerstart) und die Kette reiht sich ein
    mv $F ${F:h}/halt-bis-abgelaufen-$(date -u +%Y%m%dT%H%M%SZ).txt && { grep -qs "^$I " $KETTEN/paket-warteschlange.txt || echo "$I $(tail -1 ${F:h}/konto.txt 2>/dev/null | cut -d' ' -f1 | grep -E '^[123]$' || echo 1) $(date -u +%FT%TZ) parkzeit" >> $KETTEN/paket-warteschlange.txt; }; done
  einreihen_freigegebene   # A-55NDA7: freigegebener, grüner PR ohne Queue-Platz wird eingereiht
  local W=$(sperre $KETTEN/paket-warteschlange.lock zsh -c 'W=$(grep -m1 -E "^[0-9]+ [123] " $KETTEN/paket-warteschlange.txt); [ -n "$W" ] && { if [[ $(uname) == Darwin ]]; then sed -i "" "/^${W%% *} /d" $KETTEN/paket-warteschlange.txt; else sed -i "/^${W%% *} /d" $KETTEN/paket-warteschlange.txt; fi; }; echo $W' 2>/dev/null)   # Eintrag beim Ziehen unter Sperre entfernen: zwei gleichzeitige Enden zogen sonst denselben (10.11. 10:04); Sperrdatei wie bau-abgeben.sh auf dem Server
  [ -n "$W" ] && { ( sleep 10; cd $SKRIPT; PAKET_STARTGRUND=wartet-pr nohup ./paket.sh ${W%% *} $(echo $W | cut -d' ' -f2) > $KETTEN/paket-${W%% *}/kette.out 2>&1 & ) & }; }
# Kettengrenze: verschiedene laufende Paketnummern (Subshells tragen dieselbe Nummer), ohne die eigene
N_LAUFEN=$(ps -axo command= | grep -E '^(/[^ ]*/(zsh|bash|sh) +)?([^ ]*/)?paket\.sh [0-9]+' | sed -E 's/.*paket\.sh ([0-9]+).*/\1/' | sort -u | grep -vx $ISSUE | while read i; do [ -s $KETTEN/paket-$i/halt.txt ] || echo $i; done | wc -l | tr -d ' ')   # nur Ketten ohne Halt belegen einen Platz (wartende Ketten im Neustart-Schlaf verbrauchen nichts; Antonio-Grenze meint Usage)
GRENZE=$MAX_KETTEN; [[ "$KONTO" == [13] && $(date +%Y%m%d%H%M) -lt 202611150000 && $MAX_KETTEN -lt 6 ]] && GRENZE=6   # Antonio 11.11. 22:45: bis Sa 14.11. 23:59 Ortszeit sechs Ketten, die sechste nur auf Konto 1 und 3; danach gilt MAX_KETTEN (Rücknahme: diese Zeile entfernen und $GRENZE unten durch $MAX_KETTEN ersetzen, oder cp paket.sh.bak-20261111g paket.sh)
[ -z "$MAC" ] && { AMPEL_K=$(timeout 25 python3 -B $HOME/Bereiche/openclaw/lastschutz/lastampel.py --ketten 2>/dev/null | grep -E '^[0-9]+$' | head -1); [ "${AMPEL_K:-0}" -lt "$GRENZE" ] && GRENZE=${AMPEL_K:-0}; }   # LINUX: der Server nimmt nur so viele Ketten, wie seine Lastampel zulässt (Fehler = 0, Überlauf auf den Mac)
if [ "$N_LAUFEN" -ge "$GRENZE" ]; then grep -qs "^$ISSUE " $KETTEN/paket-warteschlange.txt || echo "$ISSUE $KONTO $(date -u +%FT%TZ) $(pcmd $PPID | cut -c1-100)" >> $KETTEN/paket-warteschlange.txt; echo "wartet auf Platz ($N_LAUFEN Ketten laufen)" | tee $LOG/halt.txt; start_log wartet; phase wartet-platz "freier Platz ($N_LAUFEN Ketten laufen)" 0; exit 3; fi   # LAGE-1115: Phase wartet-platz
sedi "/^$ISSUE /d" $KETTEN/paket-warteschlange.txt 2>/dev/null; grep -qs '^wartet auf Platz' $LOG/halt.txt && rm -f $LOG/halt.txt; rm -f $LOG/wartet-auf.txt   # zugelassen: aus der Warteschlange, alte Wartemeldung weg
start_log gestartet; LAEUFT=1; touch $LOG/.start; SKRIPT=${0:A:h}; STARTER=$(ls ~/.claude*/projects/*/${CLAUDE_CODE_SESSION_ID:-keine}.jsonl(N) 2>/dev/null | head -1 | sed -nE 's#.*/-Users-antonio--openclaw-workspace-([^/]+)/.*#\1#p'); echo "${STARTER:-}" > $LOG/starter.txt   # wer gestartet hat (OpenClaw-Agent), für die Halt-Meldung
[ -n "${PAKET_PROBE:-}" ] && exit 0   # PAKET_PROBE=1: nur Grenze, Sperre und Protokoll prüfen
phase start "" 0   # LAGE-1115: Phase start
cd "$REPO"   # Sitzungen starten in einer Kopie auf dem aktuellen master, damit CLAUDE.md und .claude/agents stimmen
gitr fetch -q hermes master && gitr checkout -q --detach hermes/master
# Werkzeuge (node tools/pruefen.mjs usw.) brauchen node_modules: npm ci, wenn die Sperrdatei sich seit dem letzten Mal geändert hat
if ! cmp -s package-lock.json node_modules/.lock-stand 2>/dev/null; then
  while ! mkdir /tmp/npm-ci-steuerung.lock 2>/dev/null; do sleep 5; done
  cmp -s package-lock.json node_modules/.lock-stand 2>/dev/null || { npm ci --no-audit --no-fund --ignore-scripts >> $LOG/npm-ci.log 2>&1 && cp package-lock.json node_modules/.lock-stand; }
  rmdir /tmp/npm-ci-steuerung.lock
fi
[ -f $LOG/start.txt ] || date -u +%FT%TZ > $LOG/start.txt
echo "$KONTO $(date -u +%FT%TZ)" >> $LOG/konto.txt
sitzung() { case $1 in pruefer-*) phase pruefer "Sitzung $1" 7200 ;; entscheiden-*) phase entscheiden "Sitzung $1" 7200 ;; *) phase bau "Sitzung $1" 7200 ;; esac   # LAGE-1115: Phase vor jeder Sitzung, Frist = Sitzungsgrenze 120 min
  case $1 in entscheiden-*) ;; *) [ "${PAKET_STARTGRUND:-}" = wartet-pr ] || [ $LOG/.gezaehlt -nt $LOG/.start ] || { echo $START >> $LOG/starts.txt; touch $LOG/.gezaehlt; } ;; esac   # Start mit Modell-Sitzung zählt für die Startgrenze (einmal je Start)
  [ -f $LOG/$1.json ] && for x in json log err; do [ -f $LOG/$1.$x ] && mv $LOG/$1.$x $LOG/$1-vorher-$(date +%s).$x; done
  case $1 in pruefer-*) MODELL=${PMODELL:-opus} ;; entscheiden-*) MODELL=opus ;; *) MODELL=sonnet ;; esac   # Steuersitzung Sonnet, Prüfer nach Einstufung aus dem Diff (einstufung); Effort medium für alle (Antonio 10.11. 12:05: Prüfer Opus, mittlerer Effort)
  ( source "$APPU" > /dev/null || exit 9; export CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS=0 PAKET_ISSUE=$ISSUE PATH=$PATH:$LOG/bin; exec $CLAUDE -p --model $MODELL --effort medium --permission-mode auto --output-format json "$2" ) > $LOG/$1.json 2> $LOG/$1.err &   # alle Sitzungen (Bau, Steuerung, Prüfer) erben die App-Umgebung (jeder Bash-Aufruf des Agenten ist eine neue Shell, ein source im Auftrag wirkte nicht weiter; #3568, #3576, #3560); unter Antonio20045 läuft nur die Kette selbst (antonio, unten)
  local P=$! T=$SECONDS   # Obergrenze je Sitzung 120 min: gemessen 08.11. Bau p90 18, max 87 min, Prüfer max 8 min
  while kill -0 $P 2>/dev/null; do (( SECONDS - T > 7200 )) && { kill $P; echo "Sitzung $1 hängt (>120 min)" > $LOG/halt.txt; exit 1; }; sleep 20; done
  jq -r '.result // ""' $LOG/$1.json > $LOG/$1.log
  LIMIT=$(grep -qiE 'rate_limit|usage limit|weekly limit|hit your limit|"status": ?429' $LOG/$1.json $LOG/$1.err 2>/dev/null && echo true || echo false)
  jq -e . $LOG/$1.json > /dev/null 2>&1 || { echo "{\"sitzung\":\"$1\",\"konto\":\"$KONTO\",\"ende\":$(date +%s),\"modell\":\"$MODELL\",\"limit\":$LIMIT,\"fehler\":true}" >> $LOG/verbrauch.jsonl; return; }
  jq -c --arg s "$1" --arg k "$KONTO" --arg md "$MODELL" --argjson l $LIMIT --argjson e $(date +%s) '(.modelUsage // {}) as $m | {sitzung:$s, konto:$k, modell:$md, ende:$e, limit:$l, kosten_usd:.total_cost_usd, ein:([$m[].inputTokens // 0]|add // 0), aus:([$m[].outputTokens // 0]|add // 0), cache_neu:([$m[].cacheCreationInputTokens // 0]|add // 0), cache_lesen:([$m[].cacheReadInputTokens // 0]|add // 0), modelle:($m|with_entries(.value={kosten:.value.costUSD, cache_lesen:.value.cacheReadInputTokens})), sek:(.duration_ms/1000|floor)}' $LOG/$1.json >> $LOG/verbrauch.jsonl 2>/dev/null
}
zerstoerend() { local T=$(mktemp -d) H=$(kopf $1) R=ja; gitr fetch -q hermes master "pull/$1/head" 2>/dev/null; [ -n "$H" ] && gitr worktree add -q --detach $T hermes/master 2>/dev/null && ( cd $T && git checkout -q $H -- src/db/migrations && node tools/pruefen.mjs migrationen --einstufung --basis hermes/master 2>/dev/null | grep -qx "Einstufung: nicht-zerstoerend" ) && R=nein; gitr worktree remove --force $T > /dev/null 2>&1; echo $R; }   # Migrations-PR: ja = zerstörend oder nicht lesbar (im Zweifel Halt für Antonio), nein = nur nicht zerstörende Muster; master-Werkzeug mit den Migrationsdateien des PR-Kopfs, die Muster stehen allein in tools/pruefen.mjs (ZERSTOERENDE_MUSTER, #4891/#4893)
einstufung() { local E=$(gh pr view $1 -R sundartha/hermes --json files --jq '.files as $f | (any($f[]; .path | startswith("src/db/migrations/"))) as $m | (($f | length) > 0 and all($f[]; (.path | test("\\.md$|^docs/")) or (.changeType == "RENAMED" and .additions + .deletions == 0)) and ([$f[] | .additions + .deletions] | add) < 50 and all($f[]; .path | test("^(src|\\.github|tools|\\.claude/agents|\\.claude/hooks)/|(^|/)package[^/]*\\.json$") | not)) as $s | "\(if $s then "sonnet" else "opus" end) \(if $m then "migration" else "-" end)"' 2>/dev/null); [ "${E#* }" = migration ] && [ "$(zerstoerend $1)" = nein ] && E="${E% *} -"; echo ${E:-opus migration}; }   # Prüfer-Modell und Migration aus dem Diff (Antonio 08.11. abends); Fehler: Opus und kein eigener Merge
lwarten() { local r n; r=$(gh api rate_limit --jq '[.resources.core, .resources.graphql] | map(select(.remaining < 5) | .reset) | max // 0' 2>/dev/null); n=$(date +%s); if [ "${r:-0}" -gt $n ] 2>/dev/null; then sleep $(( r - n + 5 > 600 ? 600 : r - n + 5 )); else sleep 20; fi; }   # leere Antwort: ist ein GitHub-Limit leer, bis zur Rücksetzung warten (höchstens 10 Min.), sonst 20 s (17.11.)
kopf() { local o i; for i in 1 2 3; do o=$(gh api repos/sundartha/hermes/pulls/$1 --jq .head.sha 2>/dev/null); [[ "$o" =~ ^[0-9a-f]{40}$ ]] && break; o=""; lwarten; done; echo "$o"; }   # leere Antwort (GitHub-Limit) wird wiederholt, nicht als Wert verwendet (17.11.)
prj() { local j; j=$(gh api repos/sundartha/hermes/pulls/$1 --jq '[(if .merged then "MERGED" else (.state | ascii_upcase) end), (if .mergeable == false then "CONFLICTING" elif .mergeable == true then "MERGEABLE" else "UNKNOWN" end), .head.sha] | join(" ")' 2>/dev/null); read PRS PRM PRK <<< "$j"; [ -n "$PRS" ]; }   # ein gebündelter REST-Aufruf (core statt GraphQL, 17.11.): Status, mergeable, Kopf in PRS/PRM/PRK; leere Antwort = false, Variablen leer
prtext() { local o i; for i in 1 2 3; do o=$(gh api repos/sundartha/hermes/pulls/$1 --jq '.body // ""' 2>/dev/null; echo x); [ "$o" != x ] && break; lwarten; done; printf "%s" "${o%x}" | shasum | cut -c1-8; }; nachtrag() { gh api repos/sundartha/hermes/issues/$ISSUE/comments --paginate --jq '.[] | select(.body | split("\n")[0] | test("^(#+ )?Plan-Nachtrag")) | .created_at' 2>/dev/null | sort | tail -1; }   # Prüfsumme des PR-Texts (Mutanten-Begründungen stehen dort) und Zeit des letzten Plan-Nachtrags (neuer Schnitt; Lesungen davor gelten nicht)
neustart() { local K=$(kopf $1) U; [ -z "${2:-}" ] && grep -qx "$K" $LOG/neustart.txt 2>/dev/null && return 1; U=$(gh pr view $1 -R sundartha/hermes --json statusCheckRollup --jq '[.statusCheckRollup | group_by(.name)[] | (map(select(.conclusion != "CANCELLED")) as $n | if ($n | length) > 0 then $n else . end) | max_by(.completedAt // "") | select((.conclusion == "FAILURE" or .conclusion == "CANCELLED" or .conclusion == "TIMED_OUT") and ((.detailsUrl // "") | test("/runs/[0-9]+"))) | .detailsUrl | capture("/runs/(?<r>[0-9]+)").r] | unique | join(" ")' 2>/dev/null); [ -n "$U" ] || return 1; [ -n "${2:-}" ] || echo $K >> $LOG/neustart.txt; for r in ${=U}; do gh run rerun $r -R sundartha/hermes --failed > /dev/null 2>&1; done; sleep 30; }   # Rot außerhalb des Diffs: einmal je Kopf alle roten Jobs neu (Umgebung: 504, Wackler; Befund 2, 09.11.); mit $2 ohne Zählung (nur PR-Text geändert, Mutation liest ihn neu)
cwarten() { local i=0 P T=$SECONDS; rm -f $LOG/.ci-frist; phase ci "PR $1" ${PAKET_CI_FRIST:-5400}; while [ "$(gh pr view $1 -R sundartha/hermes --json statusCheckRollup --jq '.statusCheckRollup | length' 2>/dev/null)" = 0 ] && [ $i -lt 90 ]; do sleep 20; i=$((i + 1)); done; local rc O; while :; do O=$(gh pr checks $1 -R sundartha/hermes 2>/dev/null); if [ -z "$O" ]; then rc=1; else rc=$(awk -F'\t' '{ if ($2 == "fail") { f_alle=1; if ($1 != "Freigabe-Prüfung") f_andere=1 } else if ($2 == "pending") { p_alle=1; if ($1 != "Freigabe-Prüfung") p_andere=1 } } END { if (f_andere) print 1; else if (p_andere) print 8; else if (f_alle) print 1; else if (p_alle) print 8; else print 0 }' <<< "$O"); fi; [ $rc -ne 8 ] && return $rc; (( SECONDS - T > ${PAKET_CI_FRIST:-5400} )) && { echo "Prüfungen an PR $1 nach $(( ${PAKET_CI_FRIST:-5400} / 60 )) Minuten nicht fertig" > $LOG/halt.txt; touch $LOG/.ci-frist; exit 1; }; sleep 60; done; }   # 17.11.: Abfrage je Minute über die gh-Funktion (App-Token, 15.000/h) statt „--watch“ (lief mit dem Nutzerkonto und hielt ein abgelaufenes Token fest); Rückgabe wie bisher: 0 grün, sonst rot (8 = noch offen)   # LAGE-1115: CI-Warten höchstens 90 min (PAKET_CI_FRIST s), dann Halt über den vorhandenen Weg; ci_lage läuft in $(…): dort hält der Aufrufer über .ci-frist   # wartet erst, bis GitHub die Check-Läufe meldet (queued: „no checks reported“ beendete --watch sofort und galt als rot; 3480, 11.11.), dann auf deren Ende   # A-K5M3CC 26.11.: sind alle anderen Checks fertig, zählt die Freigabe-Prüfung wieder mit (rot/offen -> 1/8 statt fälschlich 0); solange noch ein anderer Check offen ist, hält sie den Rücklauf nicht auf
pflicht_ausser_urteil() { local O R G n RN; O=$(gh pr checks $1 -R sundartha/hermes 2>/dev/null); if [ -z "$O" ]; then PAU_GRUND=FEHLER; return 1; fi; if awk -F'\t' '$2 != "pass" && $2 != "skipping" && $1 != "Freigabe-Prüfung" {f = 1} END {exit !f}' <<< "$O"; then RN=$(awk -F'\t' '$2 == "fail" && $1 != "Freigabe-Prüfung" {print $1; exit}' <<< "$O"); PAU_GRUND=${RN:+ROT:$RN}; PAU_GRUND=${PAU_GRUND:-PENDING}; return 1; fi; R=$(awk -F'\t' '$1 == "Freigabe-Prüfung" && $2 == "fail" {print $4}' <<< "$O" | sed -nE 's#.*/runs/([0-9]+).*#\1#p' | head -1); [ -z "$R" ] && return 0; G=$(gh run view $R -R sundartha/hermes --log-failed 2>/dev/null); if [ -z "$G" ] && ! grep -qx "$R" $LOG/neulog.txt 2>/dev/null; then echo $R >> $LOG/neulog.txt; gh run rerun $R -R sundartha/hermes --failed > /dev/null 2>&1; for n in $(seq ${PAKET_URTEIL_VERSUCHE:-9}); do sleep ${PAKET_URTEIL_WARTE:-10}; G=$(gh run view $R -R sundartha/hermes --log-failed 2>/dev/null); [ -n "$G" ] && break; done; fi; if grep -q "Es fehlt das KI-Urteil" <<< "$G" && ! grep -qE "Prüfregel auf Branch|kommt nur vom Bau-Agenten" <<< "$G"; then return 0; fi; PAU_GRUND="ROT:Freigabe-Prüfung"; return 1; }   # Freigabe-Prüfung am PR (freigabe-am-pr 25.11.): wird erst durch das Approve grün, das die Kette nach PASS selbst setzt; vor dem Approve darf sie als einzige nicht grün sein, aber nur wegen des fehlenden KI-Urteils (Deadlock-Schutz). Prüfregel- und Herkunftsbefunde und jede andere nicht grüne Prüfung bleiben ein Halt. Leeres Log (abgelaufen) hielt bisher sofort als Halt (Deadlock: Freigabe-Prüfung wird erst durch das Approve grün, das PASS erst danach setzt); jetzt einmal je Kopf (Lauf $R, neulog.txt) `gh run rerun --failed`, bis ~90 s auf ein lesbares Log warten, erst dann wie bisher entscheiden (A-DXDZU8, 26.11.). Setzt bei Rückgabe 1 zusätzlich PAU_GRUND (FEHLER = leere/fehlgeschlagene gh-Antwort, PENDING, oder ROT:<Name>), damit die Merge-Warteschleife rot von pending und von einem bloßen Lesefehler trennen kann (A-TGA9A5-Nachbesserung 26.11.); Rückgabewert unverändert.
rote_neu() {   # A-XX5EVA: nach dem Approve werden alte rote Läufe auf dem aktuellen Kopf neu gestartet: Freigabe-Prüfung und "CI" (Hauptlauf und Hilfslauf CI-Text-Lauf teilen den Namen); jeder rote Check, der wirklich nicht grün ist, jedes Mal neu, nicht nur einmal
  local R; for R in $(gh pr checks $1 -R sundartha/hermes 2>/dev/null | awk -F'\t' '($1 == "Freigabe-Prüfung" || $1 == "CI") && $2 == "fail" {print $4}' | sed -nE 's#.*/runs/([0-9]+).*#\1#p' | sort -u); do gh run rerun $R -R sundartha/hermes --failed > /dev/null 2>&1; done
}
urteil_gruen() { local i; for i in $(seq 30); do gh pr checks $1 -R sundartha/hermes 2>/dev/null | awk -F'\t' '$1 == "Freigabe-Prüfung" {if ($2 == "pass") ok = 1; if ($2 == "fail") bad = 1} END {exit !(ok && !bad)}' && return 0; (( i % 6 == 0 )) && rote_neu $1; sleep 10; done; return 1; }   # nach dem Approve wird die Freigabe-Prüfung am PR grün (Review-Ereignis); bleibt ein alter roter Lauf (Freigabe-Prüfung oder CI) stehen, wird er jede Minute neu gestartet (A-XX5EVA); bis 5 min
ci_lage() { local J K X j c n G= U= A=; if [ -n "${PAKET_CI_LAEUFE:-}" ]; then J=$(for r in ${=PAKET_CI_LAEUFE}; do gh run view $r -R sundartha/hermes --json jobs --jq '.jobs[] | select(.conclusion == "failure" or .conclusion == "cancelled" or .conclusion == "timed_out") | select((.name // "") | startswith("Vorprobe Node") | not) | "\(.databaseId)\t\(.conclusion | ascii_upcase)\t\(.name)"'; done); else cwarten $1 > /dev/null 2>&1; J=$(gh pr view $1 -R sundartha/hermes --json statusCheckRollup --jq '.statusCheckRollup | group_by(.name // .context)[] | (map(select(.conclusion != "CANCELLED")) as $n | if ($n | length) > 0 then $n else . end) | max_by(.completedAt // "") | select(((.name // "") | contains("${{")) and .conclusion == "CANCELLED" | not) | select(((.name // .context) // "") | startswith("Vorprobe Node") | not) | (.conclusion // .state) as $c | select(["FAILURE","CANCELLED","TIMED_OUT","STARTUP_FAILURE","ERROR","ACTION_REQUIRED"] | index($c)) | "\([(.detailsUrl // "") | match("/job/([0-9]+)").captures[0].string][0] // "0")\t\($c)\t\(.name // .context)"' 2>/dev/null); fi; K=$(kopf $1)   # CI ohne Modell (A-327YVH): wartet auf alle Checks; rot außer CI, Testschutz, Freigabe-Prüfung ist Diff; Umgebung ist nur Abbruch, Rüstschritt oder ein Tests-Job, der noch nicht neu gestartet wurde (Kopf nicht in neustart.txt: der Aufrufer startet neu, dann gilt: weiter rot auf demselben Kopf = Diff, grün = Wackler und gruen; Rettungskonzept Schritt 4, 13.11.). Vorprobe-Node-Jobs (freiwillig, continue-on-error) zählen nie als Diff/Rücklauf (#6296). Ausgabe: gruen | umgebung <Jobs> | diff <Jobs> und Log-Auszug. PAKET_CI_LAEUFE="<Lauf-IDs>": Trockenlauf gegen alte Läufe, ohne Warten
  while IFS=$'\t' read -r j c n; do case "$n" in ""|CI|Testschutz|Freigabe-Prüfung) continue ;; esac; X=; [ "$j" != 0 ] && X=$(gh api repos/sundartha/hermes/actions/jobs/$j --jq '[.steps[] | select(.conclusion == "failure") | .name] | join(",")' 2>/dev/null); if [ "$c" != FAILURE ] || { [ "$j" != 0 ] && [ -z "$X" ]; } || grep -qE '^(Set up job|Checkout|Node 22 und npm ci|Postgres starten|Abdeckung laden)' <<< "$X"; then U+="$n, "; elif [[ $n == (Tests|Web-Tests)* ]] && ! grep -qx "$K" $LOG/neustart.txt 2>/dev/null; then U+="$n, "; else G+="$n, "; A+="== $n (Job $j) =="$'\n'"$([ "$j" != 0 ] && gh run view --job $j -R sundartha/hermes --log-failed 2>/dev/null | cut -f3- | cut -c30-330 | grep -vE '^ *$|^(shell|env):|^  [A-Z_]+: |^##\[(end)?group\]' | grep -B20 '##\[error\]' | grep -v '^--$' | tail -60)"$'\n'; fi; done <<< "$J"
  if [ -n "$G" ]; then echo "diff ${G%, }"; head -c 6000 <<< "$A"; elif [ -n "$U" ]; then echo "umgebung ${U%, }"; elif [ -z "${PAKET_CI_LAEUFE:-}" ] && [ "$(gh pr view $1 -R sundartha/hermes --json statusCheckRollup --jq '[.statusCheckRollup[] | select(.name == "CI")] | max_by(.completedAt // "") | .conclusion // empty' 2>/dev/null)" = FAILURE ]; then echo "umgebung CI (Sammel-Job rot, kein roter Teil-Job gefunden; #4443)"; else echo gruen; fi; }   # nie gruen, wenn der Sammel-Job CI selbst rot ist (#4443: PASS auf roter CI)
stoerung_abwarten() { local i; for i in $(seq 24); do curl -s --max-time 20 https://www.githubstatus.com/api/v2/components.json | jq -e '[.components[] | select((.name == "Actions" or .name == "Pull Requests") and .status != "operational")] | length > 0' > /dev/null 2>&1 || return 0; sleep 300; done; return 1; }   # GitHub-Störung bei Actions/PRs: bis 120 min warten statt Halt (10.11. 17:11: Störung, 3387 hielt nach 90 s)
ausgeloest() { gh api "repos/sundartha/hermes/actions/runs?head_sha=$(kopf $1)&event=pull_request" --jq '[.workflow_runs[].path] | index(".github/workflows/ci.yml") != null' 2>/dev/null | grep -qx true; }   # CI-Lauf (Workflow-Datei ci.yml, nicht der Name: der Laufname ist der PR-Titel, 25.11.) für genau diesen Kopf vorhanden
aktuell() { local K=$(kopf $1); grep -qx "$K" $LOG/rebase.txt 2>/dev/null && return 1   # vor Urteil und Zählen: liegt der PR hinter master, rebased die Kette einmal je Stand selbst (App), dann wird neu geprüft (Befund 2, 09.11.)
  [ "$(gh api repos/sundartha/hermes/compare/master...$K --jq .behind_by 2>/dev/null)" -gt 0 ] 2>/dev/null || return 1
  ( source "$APPU" > /dev/null && gh pr update-branch $1 -R sundartha/hermes --rebase > /dev/null 2>&1 ) || return 1; sleep 20; kopf $1 >> $LOG/rebase.txt; }
pass_auf_kopf() { local K=${2:-$(kopf $1)}; [ -n "$K" ] && grep -qx "$1 $K" $LOG/pass.txt 2>/dev/null; }; antonio() { env -u GH_TOKEN -u GITHUB_TOKEN /opt/homebrew/bin/gh "$@"; }   # gh als Antonio20045 (gespeicherter Login, nie die App, auch wenn der App-Wrapper vorn im PATH liegt): nur was GitHub von ihm verlangt – Approve, Einreihen, Urteils-Label
approve() { local K=${2:-$(kopf $1)}; [ -n "$(gh api repos/sundartha/hermes/pulls/$1/reviews --paginate --jq ".[] | select(.state == \"APPROVED\" and .commit_id == \"$K\" and (.user.login == \"Antonio20045\" or .user.login == \"jonas986\")) | .id" 2>/dev/null)" ]; }   # Approve eines zugelassenen Freigebers auf dem aktuellen Kopf (die App zählt nicht)
pass_am_pr() { local K=$(kopf $1); [ ${#K} -ge 7 ] && gh pr view $1 -R sundartha/hermes --json comments,reviews --jq "[.comments[], .reviews[]] | .[] | select((.createdAt // .submittedAt) > \"$2\" and (.body | split(\"\n\")[0] | test(\"PASS|LESUNG OK\")) and (.body | contains(\"${K:0:7}\"))) | .body" 2>/dev/null | grep .; }   # PASS-Urteil steht AM PR seit Sitzungsbeginn (von der App) und nennt den aktuellen Kopf (Leiter 09.11.: sonst Lockerung; altes PASS gibt nie frei); Erfolg = es gibt eines, ausgegeben wird sein Text (daraus die Zeile "Labels:")
eingereiht() { [ "$(gh api graphql -f query="{repository(owner:\"sundartha\",name:\"hermes\"){pullRequest(number:$1){isInMergeQueue state mergeStateStatus autoMergeRequest{enabledAt}}}}" --jq '.data.repository.pullRequest | .isInMergeQueue or .state == "MERGED" or (.autoMergeRequest != null and .mergeStateStatus != "CLEAN")' 2>/dev/null)" = true ]; }   # in der Merge-Queue, gemergt oder zum Einreihen vorgemerkt (gh pr merge wartet auf Pflicht-Checks, #3610)
queue_rot() { local R=$(gh api "repos/sundartha/hermes/actions/runs?event=merge_group&per_page=100" --jq "[.workflow_runs[] | select(.conclusion == \"failure\" and (.head_branch | test(\"/pr-$1-\")))] | max_by(.created_at) | .id // empty" 2>/dev/null); echo "$(gh api repos/sundartha/hermes/actions/runs/${R:-0}/jobs --jq '[.jobs[] | select(.conclusion == "failure" and .name != "CI") | .name] | join(", ")' 2>/dev/null | grep . || echo unbekannt) (Queue-Lauf ${R:-unbekannt}, PR #$1)"; }   # rote Prüfung(en) des letzten fehlgeschlagenen Queue-Laufs
freigeben() { approve $1 || { pass_am_pr $1 1970-01-01T00:00:00Z > /dev/null && antonio pr review $1 -R sundartha/hermes --approve --body "Freigabe nach PASS des Prüf-Agenten (von der Kette gesetzt)" > /dev/null 2>&1 && echo "PR $1: Approve gesetzt" >> $LOG/nachgetragen.txt; }; approve $1 && { eingereiht $1 || { urteil_gruen $1; antonio pr merge $1 -R sundartha/hermes --disable-auto > /dev/null 2>&1; local EF; EF=$(antonio pr merge $1 -R sundartha/hermes 2>&1 > /dev/null); if [ $? -eq 0 ]; then echo "PR $1: Einreihen gesetzt" >> $LOG/nachgetragen.txt; elif [[ "$EF" == *workflow*scope* ]]; then echo "Einreihen braucht workflow-Berechtigung: Antonio klickt Merge when ready (PR $1) oder gh auth refresh -s workflow" > $LOG/halt.txt; exit 1; fi; sleep 5; }; }; approve $1 && eingereiht $1 || { echo "Freigabe nicht ausgeführt (PR $1)" > $LOG/halt.txt; exit 1; }; }   # PASS ohne Migration: Approve (Antonio20045) auf dem Kopf UND Merge-Queue; beides macht die Kette, der Prüfer läuft unter der App und gibt nie frei (#3469, #3489, #3500) – nur mit Approve einreihen; "already queued" zählt über das erneute Lesen
merge_entscheidung() {   # reine Funktion (Test lädt sie, A-TGA9A5 26.11., Nachbesserung 26.11.): $1 Approve auf dem Kopf (1/0), $2 Pflicht-Zustand aus pflicht_ausser_urteil/PAU_GRUND ("" grün, PENDING, FEHLER bei leerer gh-Antwort, oder ROT:<Name>), $3 PASS auf dem Kopf (1/0); Ausgabe WEITER, FREIGEBEN, ROTE_NEU oder HALT:<Grund> für genau eine Messung – die Aufrufstelle entscheidet, ob ein HALT erst nach zwei übereinstimmenden Messungen wirkt
  case "$2" in
    ROT:Freigabe-Prüfung|ROT:CI) [ "$1" = 1 ] && { echo ROTE_NEU; return; }; echo "HALT:Pflicht-Check außer Freigabe-Prüfung rot"; return ;;   # eher ein alter/verwaister Lauf als ein echter Befund, rote_neu startet ihn neu statt zu halten; sonst (kein Approve dazu) bleibt es ein Halt
    ROT:*) echo "HALT:Pflicht-Check rot (${2#ROT:})"; return ;;   # echtes Fail eines anderen Pflicht-Checks: kein Neustart-Kandidat, bleibt auch mit Approve ein Halt
  esac   # PENDING und FEHLER (leere/fehlgeschlagene gh-Antwort) sind kein Befund: weder Neustart noch eigener Halt-Grund, fallen auf die Approve-Prüfung durch
  if [ "$1" = 0 ]; then [ "$3" = 1 ] && { echo FREIGEBEN; return; }; echo "HALT:kein Approve auf dem aktuellen Kopf"; return; fi   # nur das Approve fehlt (kein roter Pflicht-Check): bei gültigem PASS die Freigabe selbst nachholen statt zu warten
  echo WEITER
}
lesung() { gh pr view $1 -R sundartha/hermes --json comments,reviews --jq "[(.comments[] | select(.createdAt > \"$(nachtrag)\" and (.body | split(\"\n\")[0] | test(\"^(LESUNG OK|FAIL) ${2:0:7} $3\"))) | {t: .createdAt, b: .body}), (.reviews[] | select(.state == \"CHANGES_REQUESTED\" and .submittedAt > \"$(nachtrag)\" and (.commit.oid | startswith(\"${2:0:7}\"))) | {t: .submittedAt, b: (\"FAIL ${2:0:7} $3: Review mit Änderungswunsch am Kopf: \" + .body)})] | sort_by(.t) | last | .b // empty" 2>/dev/null; }   # Lesung des Prüfers zu Kopf und PR-Text, am PR (A-327YVH: genau eine je Kopf, überlebt Neustarts; ersetzt PK= und fail.txt)
stellen() { local Z=$(grep . $4 2>/dev/null | tail -1 | tr -d '*`') E; case "$Z" in "LESUNG OK"*) E="LESUNG OK ${2:0:7} $3" ;; FAIL*) E="FAIL ${2:0:7} $3: ${${Z#FAIL}# }" ;; *) return 1 ;; esac; print -r -- "$E"$'\n\n'"$(cat $4)" | ( source "$APPU" > /dev/null && gh pr comment $1 -R sundartha/hermes --body-file - > /dev/null 2>&1 ); }   # die Kette stellt die Antwort des Prüfers als Lesung an den PR: ein Schreiber, festes Format (#3545: Urteil fehlte am PR)
ruecklaeufe() { local S=$(grep "^$1 " $LOG/schnitt.txt 2>/dev/null | tail -1 | cut -d' ' -f2) P=$(nachtrag); [[ "$P" > "$S" ]] && S=$P; gh pr view $1 -R sundartha/hermes --json comments,reviews --jq "[([.comments[] | select(.createdAt > \"$S\" and (.body | split(\"\n\")[0] | test(\"Urteil.*FAIL|^FAIL|^CI ROT \")))] | length), ([.reviews[] | select(.state == \"CHANGES_REQUESTED\" and .submittedAt > \"$S\")] | length)] | max"; }   # Rückläufe seit dem letzten Schnitt (ein Plan-Nachtrag ist einer, 10.11.: #3492, #3553, #3387): nur FAIL-Lesungen und CI-Rot im Diff am PR; Wackler, Testschutz, Umgebung zählen nie (A-327YVH)
umzug() { local P=$1 B NB K R T NEU L; [ "$2" = - ] && ! grep -qx "$P" $LOG/umzug.txt 2>/dev/null || return 1   # Kette zieht Prüfregel-PRs selbst auf system/* um (10.11.: 3793→3797, 3801→3802 von Hand): nur wenn PASS auf dem Kopf, keine Migration und die Freigabe-Prüfung der einzige rote Check ist, weil der Log Prüfregel-Dateien auf paket/* meldet (tools/freigabe.mjs, SCHRANKE_AUSWEG); Prüfer-PASS und Approve bleiben Pflicht, PASS gilt für denselben Kopf weiter. PAKET_UMZUG_TROCKEN=1: nichts schreiben, Befehle ausgeben
  t() { [ -n "${PAKET_UMZUG_TROCKEN:-}" ] && echo "[trocken] $*" >&2 || "$@"; }
  B=$(gh pr view $P -R sundartha/hermes --json headRefName --jq .headRefName 2>/dev/null); [[ $B == paket/* ]] || return 1; NB=system/${B#paket/}; K=$(kopf $P)
  R=$(gh pr view $P -R sundartha/hermes --json statusCheckRollup --jq '[.statusCheckRollup | group_by(.name)[] | (map(select(.conclusion != "CANCELLED")) as $n | if ($n | length) > 0 then $n else . end) | max_by(.completedAt // "") | select(.conclusion == "FAILURE" or .conclusion == "CANCELLED" or .conclusion == "TIMED_OUT")] | if length == 1 and .[0].name == "Freigabe-Prüfung" then .[0].detailsUrl else empty end' 2>/dev/null | sed -nE 's#.*/runs/([0-9]+).*#\1#p'); [ -n "$R" ] && gh run view $R -R sundartha/hermes --log-failed 2>/dev/null | grep -q "Prüfregel auf Branch paket/" || return 1
  t eval "echo $P >> $LOG/umzug.txt"; L=$(pass_am_pr $P 1970-01-01T00:00:00Z); [ -n "$L" ] || return 1; T=$(mktemp)
  NEU=$(gh pr list -R sundartha/hermes --head $NB --state open --json number --jq '.[0].number // empty' 2>/dev/null)   # schon umgezogen (von Hand oder früherer Versuch): übernehmen
  [ -n "$NEU" ] || { ( source "$APPU" > /dev/null && gitr fetch -q hermes "$B" && t gitr push -q hermes ${K}:refs/heads/$NB ) || return 1
    { gh pr view $P -R sundartha/hermes --json body --jq .body; printf '\n\nÜbernimmt #%s unverändert (Kopf %s) auf den Systemweg, weil Prüfregel-Dateien nur über system/* geändert werden dürfen.\n' $P ${K:0:7}; } > $T
    NEU=$( ( source "$APPU" > /dev/null; t gh pr create -R sundartha/hermes --base master --head $NB --title "$(gh pr view $P -R sundartha/hermes --json title --jq .title)" --body-file $T ) | grep -oE '[0-9]+$'); }
  [ -n "${PAKET_UMZUG_TROCKEN:-}" ] && NEU=${NEU:-<neu>}; [ -n "$NEU" ] || return 1
  t gh pr comment $NEU -R sundartha/hermes --body "PASS ${K:0:7} (Urteil aus #$P, Kopf unverändert übernommen)

$L" > /dev/null; for B in $(sed -nE 's/^Labels: *(verhalten-geaendert) *$/\1/p' <<< "$L" | sort -u); do t antonio api -X POST repos/sundartha/hermes/issues/$NEU/labels -f "labels[]=$B" > /dev/null; done   # Urteils-Label nur, wenn das PASS es nennt (wie die Kette sonst auch)
  t gh pr close $P -R sundartha/hermes --comment "Übernommen in #$NEU" > /dev/null; t eval "echo \"$NEU $K\" >> $LOG/pass.txt; echo \"PR $P: umgezogen auf $NB als #$NEU\" >> $LOG/nachgetragen.txt"; [ -n "${PAKET_UMZUG_TROCKEN:-}" ] || PR=$NEU; sleep 20; }
for _P in $(cut -d' ' -f1 $LOG/pass.txt 2>/dev/null | sort -u); do if ! grep -q "^$_P " $LOG/gemergt.txt 2>/dev/null; then [ "$(gh api repos/sundartha/hermes/pulls/$_P --jq .merged 2>/dev/null)" = true ] && echo "$_P $(date -u +%FT%TZ)" >> $LOG/gemergt.txt; fi; done   # Merge nachzählen, den eine tote Kette nicht gesehen hat (3986, 17.11.: PR 5032 gemergt, Startgrenze hielt trotzdem)
