    sitzung bau-$N-bewerten-$R "$KEINPLAN PR #$PR (sundartha/hermes, Teil von #$ISSUE) hat zwei Rückläufe (FAIL-Lesung oder CI-Rot im Diff am PR) oder einen Rücklauf ohne neuen Stand; ohne Bewertung wird nicht weiter nachgebessert. Bewerte anhand der letzten Kommentare FAIL bzw. CI ROT am PR und der roten Läufe auf seinem aktuellen Kopf (gh run view --log-failed), woran es liegt; Befunde früherer Köpfe, die der aktuelle Kopf schon behebt, zählen nicht, und der Plan gilt einschließlich aller Plan-Nachträge im Issue. Liegt es an der Größe des Häppchens, ist die letzte Zeile genau GROESSE. Lässt sich jeder rote Befund am PR selbst beheben (Code, Test, PR-Text) und du kannst genau sagen wie, schreib die Anweisung für den Bau zwischen eine Zeile NACHTRAG-ANFANG und eine Zeile NACHTRAG-ENDE (je Befund: Stelle, Ursache, Behebung) und als letzte Zeile genau NACHBESSERN. Liegt es woanders (Prüfwerkzeug, Umgebung, Plan widersprüchlich), ist die letzte Zeile URSACHE: <Ursache in einem Satz>. Du änderst nichts, kein Push, kein Kommentar, kein Urteil."
    if tail -1 $LOG/bau-$N-bewerten-$R.log | grep -q '^URSACHE:'; then gh issue comment $ISSUE -R sundartha/hermes --body "Paket hält bei PR #$PR nach zwei Rückläufen. $(tail -1 $LOG/bau-$N-bewerten-$R.log)" > /dev/null 2>&1; tail -1 $LOG/bau-$N-bewerten-$R.log > $LOG/halt.txt; exit 1; fi
    if tail -1 $LOG/bau-$N-bewerten-$R.log | grep -qx 'NACHBESSERN'; then   # behebbare Befunde: bis zu dreimal je PR (je neuer Kopf neue Befunde; einmal reichte nicht, 2656/2934/3475 hielten 12.11.) ein Plan-Nachtrag aus der Bewertung, er zählt als neuer Schnitt (ruecklaeufe); statt Halt (#3735, #3455 10.11.). A-VA2YWR 19.11.: die Bewertung steht immer im Issue (auch die letzte vor dem Halt); gezählt wird nur ein Nachtrag, nach dem der PR-Kopf sich geändert hat; der Halt nennt den echten Grund (5137, 5491)
      BEW=$(sed -n '/^NACHTRAG-ANFANG$/,/^NACHTRAG-ENDE$/p' $LOG/bau-$N-bewerten-$R.log | sed '1d;$d'); KN=$(kopf $PR); KL=$(grep "^$PR " $LOG/nachbessern-kopf.txt 2>/dev/null | tail -1 | cut -d' ' -f2); HG=""
      if [ -n "$KL" ] && [ "$KL" = "$KN" ]; then HG="Bau hat den letzten Plan-Nachtrag nicht umgesetzt (PR-Kopf seit dem Nachtrag unverändert; Ursache im letzten bau-$N-ruecklauf-*.log suchen)"
      elif [ "$(grep -cx "$PR" $LOG/nachbessern.txt 2>/dev/null)" -ge 3 ]; then HG="Nachbesserungsgrenze erreicht (dreimal Plan-Nachtrag umgesetzt, die Befunde der letzten Bewertung bleiben; Zähler nicht zurücksetzen)"; fi
      if [ -z "$HG" ]; then
        echo $PR >> $LOG/nachbessern.txt; echo "$PR $KN" >> $LOG/nachbessern-kopf.txt; ( source "$APPU" > /dev/null && gh issue comment $ISSUE -R sundartha/hermes --body "Plan-Nachtrag (Bewertung nach zwei Rückläufen, PR #$PR): einmalig weiter nachbessern.
$BEW" > /dev/null 2>&1 ) && { sleep 5; continue; }
        echo "PR $PR: Plan-Nachtrag der Bewertung ließ sich nicht schreiben" > $LOG/halt.txt; exit 1; fi
      ( source "$APPU" > /dev/null && gh issue comment $ISSUE -R sundartha/hermes --body "Paket hält bei PR #$PR: $HG. Letzte Bewertung (nicht umgesetzt):
$BEW" > /dev/null 2>&1 )
      echo "PR $PR: $HG; die letzte Bewertung steht im Issue #$ISSUE" > $LOG/halt.txt; exit 1; fi
    tail -1 $LOG/bau-$N-bewerten-$R.log | grep -qx 'GROESSE' || { echo "PR $PR: Bewertung nach zwei Rückläufen ohne Ergebnis" > $LOG/halt.txt; exit 1; }
    echo "$PR $(date -u +%FT%TZ)" >> $LOG/schnitt.txt   # C: nur bei Bewertung Größe; die Zählung beginnt mit dem Schnitt neu
    sitzung bau-$N-schneiden "$KEINPLAN PR #$PR (sundartha/hermes, Teil von #$ISSUE) ist nach zwei Rückläufen als zu groß bewertet. Lass den Subagenten bau (.claude/agents/bau.md, nie im Hintergrund) den PR auf ein in sich vollständiges, deutlich kleineres erstes Teilstück von höchstens 300 Zeilen kürzen (mit seinen Tests); der Rest kommt als nächstes Häppchen in den Plan-Kommentar des Issues. Du selbst änderst keinen Code. Push nur mit paket-push wie in bau.md, nicht auf die CI warten. Kein Urteil, kein Merge."
    ZEILEN=$(gh pr view $PR -R sundartha/hermes --json files --jq '[.files[] | select(.path | startswith("test/") or contains("/test/") | not) | .additions + .deletions] | add // 0')
    [ "${ZEILEN:-0}" -gt 300 ] && { echo "PR $PR hat nach dem Schneiden noch $ZEILEN Zeilen" > $LOG/halt.txt; exit 1; }
  done
  MWHALT=""; MWHALTN=0
  phase merge "PR $PR" 3600; MWT=$SECONDS; MWLETZT=$SECONDS; while (( SECONDS - MWT < 3600 )); do   # LAGE-1115/A-TGA9A5: Frist per Wanduhr statt Rundenzahl (60 Runden mit mehreren API-Aufrufen plus je sleep 60 liefen über 60 Min., 6183/6344/5927 standen 1,5 h+, 26.11.) · Merge abwarten; fällt der PR (PASS, Approve, Pflicht-Checks grün, Kopf unverändert) aus der Queue (Queue-Lauf rot durch Wackler, #3633), bis zu dreimal wieder einreihen (requeue.txt: Wackler in der Queue kippten 12.11. 6 Ketten, jeweils ein Neustart genügt nicht), beim vierten Rauswurf Halt. MWHALT/MWHALTN (unten): ein HALT-Kandidat der 5-Minuten-Prüfung wirkt erst, wenn dieselbe Messung zweimal in Folge (5 Min. Abstand) kommt (Nachbesserung 26.11.: eine leere/fehlgeschlagene gh-Antwort darf nie allein halten)
    prj $PR; S=$PRS; [ "$S" = MERGED ] && break; [ "$S" = CLOSED ] && { echo "PR $PR: ohne Merge geschlossen, die Kette baut weiter" >> $LOG/nachgetragen.txt; wegraeumen $PR; continue 2; }   # eine REST-Abfrage je Runde: Status, mergeable und Kopf (PRS/PRM/PRK) für die Zeilen darunter
    [ "$S" = OPEN ] && [ "$PRM" = CONFLICTING ] && continue 2   # Konflikt nach Einreihung (4346, 14.11.: 75 Min. Warten bis zum Halt): zurück in die Runde, dort rebased der Rücklauf
    [ "$S" = OPEN ] && [ "$(gh api "repos/sundartha/hermes/commits/$PRK/check-runs?per_page=100" --jq '[.check_runs[] | select(.name == "CI")] | max_by(.completed_at // "") | .conclusion // empty' 2>/dev/null)" = failure ] && { aktuell $PR; true; } && continue 2   # CI rot: zurück in die Runde statt 60 Min. auf einen roten PR zu warten (4959, 17.11.: Rotprobe rot, Kette schlief bis zum Halt); liegt der PR hinter master, rebased aktuell einmal je Kopf (3400, 16.11.) rebasen, neuer Kopf = neues Urteil
    if [ "$S" = OPEN ] && (( SECONDS - MWLETZT >= 300 )); then   # A-TGA9A5: etwa alle 5 Min. statt erst nach der ganzen Stunde prüfen, ob der Kopf ein Approve hat und ob ein Pflicht-Check außer der Freigabe-Prüfung rot ist; vorher gab es dafür keinen Halt, nur die Pfade für CONFLICTING und rote CI oben
      MWLETZT=$SECONDS; MWA=0; approve $PR $PRK && MWA=1; MWR=""; pflicht_ausser_urteil $PR || MWR=$PAU_GRUND; MWP=0; pass_auf_kopf $PR $PRK && MWP=1
      MWE=$(merge_entscheidung $MWA "$MWR" $MWP)
      case $MWE in
        ROTE_NEU) rote_neu $PR; MWHALT=""; MWHALTN=0 ;;
        FREIGEBEN) freigeben $PR; MWHALT=""; MWHALTN=0 ;;
        HALT:*) [ "$MWE" = "$MWHALT" ] && MWHALTN=$(( MWHALTN + 1 )) || { MWHALT=$MWE; MWHALTN=1; }; (( MWHALTN >= 2 )) && { echo "PR $PR: ${MWE#HALT:} (Kopf ${PRK:0:7})" > $LOG/halt.txt; exit 1; } ;;
        *) MWHALT=""; MWHALTN=0 ;;
      esac
    fi
    [ "$S" = OPEN ] && ! eingereiht $PR && { sleep 15; ! eingereiht $PR; } && pass_auf_kopf $PR $PRK && approve $PR $PRK && gh pr checks $PR -R sundartha/hermes --required > /dev/null 2>&1 && {
      [ "$(grep -c "^$PR " $LOG/requeue.txt 2>/dev/null)" -ge 3 ] && { echo "dreimal wieder eingereiht, jedes Mal aus der Queue gefallen: $(queue_rot $PR)" > $LOG/halt.txt; exit 1; }; antonio pr merge $PR -R sundartha/hermes --rebase --auto > /dev/null 2>&1 && echo "$PR $(date -u +%FT%TZ)" >> $LOG/requeue.txt; }
    sleep 60
  done
  [ "$(gh pr view $PR -R sundartha/hermes --json state --jq .state)" = "MERGED" ] || { echo "PR $PR nicht gemergt nach 60 Min." > $LOG/halt.txt; exit 1; }
  echo "$PR $(date -u +%FT%TZ)" >> $LOG/gemergt.txt; wegraeumen $PR
done
